#!/bin/sh
# audit D2 (THM-5056): reproduce every audit computation.  Run from this directory:  sh run_d2.sh > run_d2.out 2>&1
# Needs ../dom_K511.out (gitignored), regenerated by the repo's own census code:
#   cd .. && gcc -O2 -o dom_even ../paleyeven_20261109/dom_even.c && ./dom_even 511 16 > dom_K511.out   (~20 s)
# Total running time about 1-2 minutes.  No third-party code.
set -e
echo "== compile (own checkers; the session's wcheck.c only for its own re-run)"
gcc -O2 -Wall -o d2check d2check.c
gcc -O2 -Wall -o d2small d2small.c
gcc -O2 -Wall -o d2allsmall d2allsmall.c
gcc -O2 -o wcheck_session ../wcheck.c
echo "== census hash (expect 6307dfa1d0fc58de7cd0990b1c4c948064d2be4f4a0c5846f9135df50d0afd0e, as in ../sha256.txt)"
shasum -a 256 ../dom_K511.out
echo "== (A) the session's witness files, regenerated with the session's own scripts into this directory"
(cd .. && python3 oddbuild.py 3 8192 0 audit_d2/oddw_small_regen.txt \
       && python3 oddbuild.py 8192 1048576 300 audit_d2/oddw_large_regen.txt \
       && python3 oddspecial.py audit_d2/oddw_special_regen.txt)
shasum -a 256 oddw_small_regen.txt oddw_large_regen.txt oddw_special_regen.txt
for f in small large special; do
  echo "-- oddw_${f}: session wcheck, then audit d2check"
  ./wcheck_session < oddw_${f}_regen.txt
  ./d2check < oddw_${f}_regen.txt
done
echo "== (B) d2check controls (expected: K2, P4, K4e OK; the other five FAIL)"
./d2check verbose < controls.txt || true
echo "== (C) exhaustive labelled enumeration, connected graphs n <= 7, vs census per (n, d, parity)"
./d2small 7 > d2small.out
grep -E "^(REP|MIN)" d2small.out
python3 d2cmp_small.py d2small.out ../dom_K511.out
echo "== (D) the final statement for n <= 7 over ALL labelled graphs (no census, no construction)"
./d2allsmall > d2allsmall.out
grep -E "count=|MATCH" d2allsmall.out
echo "== (E) base below 512, recomputed (census used only as a candidate list)"
python3 d2base.py ../dom_K511.out d2base_witnesses.txt > d2base.out
cat d2base.out
./d2check < d2base_witnesses.txt
echo "== (F) independent re-implementation of the construction, random admissible choices"
python3 d2build.py all:512:16384 d2w_all.txt 11
./d2check < d2w_all.txt
python3 d2build.py rand:16384:2097152:500 d2w_rand.txt 12
./d2check < d2w_rand.txt
python3 d2build.py special:21 d2w_special.txt 13
./d2check < d2w_special.txt
echo "== (G) seeds, every admissible w, 513"
python3 d2seeds.py
echo "== (H) lemma tests"
python3 d2lemmas.py
echo "== (I) symbolic sweep of the case analysis, odd k < 2^24"
python3 d2induct.py 24
echo "== (J) base values with no twin-carrying realiser on L(k) vertices; the odd realisers of 17"
python3 d2twins.py ../dom_K511.out
./d2check full < c17.txt
echo "== done"
